    dofs[27] = offset + 3 * entity_indices[2][0];
    dofs[28] = offset + 3 * entity_indices[2][0] + 1;
    dofs[29] = offset + 3 * entity_indices[2][0] + 2;
    offset += 3 * num_global_entities[2];
